    KDF_D(pWorkSpace, pNonce, &(mDomainBundleEphemeral.mTwistConstants), &(mDomainBundleEphemeral.mTwistSalts), ARX_STATE_VARS);
    //
    TwistFarm::Farm(pFarmSalt,
                    aVaporLaneA, aVaporLaneB, aVaporLaneC, aVaporLaneD, // farm lanes
                    aFuseLaneA, aFuseLaneB, aFuseLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mTwistSalts,
                    &(pWorkSpace->mDomainBundle.mTwistConstants));
    //
    //
    ////////////////////////////////////////////////////////
    //
    // Seed
    //
    aIngress = 0x8EA8D17E3DB04FBEULL;
    aCarry = 0xAF609BC83317D1EFULL;
    aWandererA = 0xD9074D120B5738F5ULL;
    aWandererB = 0xF98D9D689C8900FAULL;
